","start":10,"end":12,"requiresContextualInterpretation":true}]},"consistency":{"policyVersion":"interview-evidence-1.0.0","scope":"project-interview-stage-application;not-an-automatic-classical-verdict","use":{"relation":"use_controls_body","text":"用克体，名不可成。","sourceId":"mh-071"},"end":{"relation":"body_generates_use","text":"体生用，名不可就，或因名有丧。","sourceId":"mh-071"},"generatingRoles":[],"movingLineAdverseTerms":true,"noGenerationWithUseControl":true,"reliefIsNotAttainment":{"sourceIds":["mh-071","mh-116","mh-119"],"reason":"旺体、克体气衰、互卦比和可减轻牵制，未另有成就依据时不翻为通过。"},"authorResolution":[{"fact":"两互比和，仍有配合","resolution":"同为春死之土，配合不足以承接旺木克体，末后又泄体，结合征凶取当前未通过。"}],"independentReviewStatus":"pending"},"indirectEffectsApplied":[],"interpretationProvenance":"assistant-authored;not-observed-feedback;not-scientifically-verified-prediction"},"copy":{"title":"起步牵制较重，这轮偏难通过","short":{"decisionId":"career.interview.interview-pass/27/2/spring-wood/not-pass-this-round","text":"这轮面试倾向难以通过。开头的要求较难承接，中间虽有配合，推动仍偏弱，末后还要继续花精力。回答宜回到真实经历和已经做过的事情，不为迎合要求勉强承诺。把能做与尚未做过的部分分清说，也继续考虑其他机会。"},"long":{"decisionId":"career.interview.interview-pass/27/2/spring-wood/not-pass-this-round","opening":"起初的牵制较明显。艮土体春令属死，震木用当旺而克体，现有条件与考察要求之间容易出现较难处理的距离。先听清所问，再讲自己能够说明的部分。","process":"中间仍有沟通余地。体互、用互都是坤土，与体比和，但春令土弱，照应的推动力有限。配合仍在，事情却不易迅速推进。","ending":"六二“颠颐，拂经，于丘颐，征凶”，对偏离正途而勉强求取持不利态度。变用兑金属囚，受体土所生，弱体仍需耗费；求名占对此也取不利于成就。这轮倾向难过，宜把回答落回事实。","summary":"本轮偏向不通过。把做过什么、能承担什么分清说，别为得到认可而顺着要求扩大承诺。"}},"timingSlots":[{"id":"result","kind":"control","role":"use","event":"本轮面试推进受阻或收到不利反馈","valence":"凶","ruleIds":["adverse-event"],"sourceIds":["mh-116","mh-143"],"prefix":"留意","suffix":"前后的本轮面试进展，推进受阻或出现不利反馈的意味较重，属凶应。","eventScope":"obstruction-or-adverse-result","calculationBasis":{"role":"use","trigram":"震","element":"木","directRelation":"use_controls_body","method":"pre-heaven-element-qi","scale":"day","ruleIds":["adverse-event"],"sourceIds":["mh-116","mh-143"],"interpretationReview":"author-source-checked","independentInterpretationReview"