PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
PRAGMA defer_foreign_keys=ON;
CREATE TABLE authored_product_manuscripts(question_id TEXT NOT NULL REFERENCES product_questions(id),hexagram_id INTEGER NOT NULL,moving_line INTEGER NOT NULL,month_order_id TEXT NOT NULL REFERENCES month_orders(id),void_profile_key TEXT NOT NULL,decision_id TEXT NOT NULL,record_json TEXT NOT NULL,review_version TEXT NOT NULL,review_status TEXT NOT NULL CHECK(review_status='author-checked'),artifact_digest TEXT NOT NULL,PRIMARY KEY(question_id,hexagram_id,moving_line,month_order_id,void_profile_key),FOREIGN KEY(hexagram_id,moving_line) REFERENCES lines(hexagram_id,position));
CREATE TABLE authored_product_month_slots(question_id TEXT NOT NULL,hexagram_id INTEGER NOT NULL,moving_line INTEGER NOT NULL,month_branch TEXT NOT NULL CHECK(length(month_branch)=1 AND instr('寅卯辰巳午未申酉戌亥子丑',month_branch)>0),month_order_id TEXT NOT NULL,void_profile_key TEXT NOT NULL,PRIMARY KEY(question_id,hexagram_id,moving_line,month_branch,void_profile_key),FOREIGN KEY(question_id,hexagram_id,moving_line,month_order_id,void_profile_key) REFERENCES authored_product_manuscripts(question_id,hexagram_id,moving_line,month_order_id,void_profile_key));
COMMIT;
